/* ---------- schémas (dessins originaux) ---------- */
const SVG_PLANE=`<svg viewBox="0 0 640 360" role="img" aria-label="Les parties d'un avion vu de dessus">
<g fill="#1d3246" stroke="#5f7d99" stroke-width="1.5"><path d="M320 22c14 0 20 22 20 48v200l46 34v14l-46-12v22h-40v-22l-46 12v-14l46-34V70c0-26 6-48 20-48z"/><path d="M300 130 52 196v18l248-34zM340 130l248 66v18L340 180z"/>
<rect x="196" y="176" width="20" height="44" rx="8"/><rect x="424" y="176" width="20" height="44" rx="8"/></g>
<g fill="#e04ad8aa"><path d="M70 207l60-9v9l-60 9z"/><path d="M570 207l-60-9v9l60 9z"/></g><g fill="#ffb020aa"><path d="M150 196l130-19v9l-130 19z"/><path d="M490 196l-130-19v9l130 19z"/></g>
<g fill="#46c8d8aa"><path d="M282 302l-30 9v6l30-6zM358 302l30 9v6l-30-6z"/></g><rect x="316" y="282" width="8" height="58" fill="#ff4a3daa"/><path d="M310 46h20v14h-20z" fill="#46c8d8"/>
<g stroke="#8ea3b8" stroke-width="1"><path d="M330 52H452"/><path d="M340 110H452"/><path d="M98 204 70 250"/><path d="M215 186 180 250"/><path d="M206 222v44"/><path d="M440 120l58-32"/><path d="M265 312H190"/><path d="M324 330h96"/><path d="M552 205l20 45"/><path d="M300 150H200"/></g>
<text x="456" y="56" class="lb">Poste de pilotage (cockpit)</text><text x="456" y="114" class="lb">Fuselage</text><text x="20" y="266" class="mg">Aileron (roulis)</text><text x="150" y="266" class="am">Volets (portance à basse vitesse)</text>
<text x="168" y="282">Moteur (réacteur) sous l'aile</text><text x="500" y="84" class="lb">Bord d'attaque, becs</text><text x="70" y="316" class="lb">Gouverne de profondeur (tangage)</text><text x="424" y="334" fill="#ff8a80">Dérive + gouverne de direction (lacet)</text>
<text x="532" y="266">Saumon, feu vert</text><text x="60" y="154">Emplanture · réservoirs dans les ailes</text></svg>`;
const SVG_FORCES=`<svg viewBox="0 0 640 300" role="img" aria-label="Les quatre forces"><path d="M170 160c40-18 230-22 300-14 30 4 40 12 40 18s-14 12-40 14c-80 6-260 2-300-12z" fill="#1d3246" stroke="#5f7d99"/><path d="M290 150l40-50h20l-20 50z" fill="#1d3246" stroke="#5f7d99"/><path d="M180 150l-24-40h16l30 40z" fill="#1d3246" stroke="#5f7d99"/>
<defs><marker id="ar" viewBox="0 0 10 10" refX="9" refY="5" markerWidth="7" markerHeight="7" orient="auto"><path d="M0 0 10 5 0 10z" fill="context-stroke"/></marker></defs>
<g stroke-width="4" fill="none" marker-end="url(#ar)"><path d="M320 150V40" stroke="#46c8d8"/><path d="M320 175v100" stroke="#ff4a3d"/><path d="M515 165h110" stroke="#3ddc84"/><path d="M165 165H40" stroke="#ffb020"/></g>
<text x="330" y="52" class="lb">PORTANCE (créée par l'aile)</text><text x="330" y="270" fill="#ff8a80">POIDS (gravité)</text><text x="520" y="150" fill="#3ddc84">POUSSÉE (moteurs)</text><text x="20" y="150" class="am">TRAÎNÉE (résistance de l'air)</text>
<text x="190" y="215">Vol en palier stabilisé : portance = poids, poussée = traînée</text></svg>`;
